import{z as n,x as C,o as l,c as o,q as B,j as s,D as e,d as A,s as i,S as r,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"质量过滤：打分器与一致性","description":"","frontmatter":{"title":"质量过滤：打分器与一致性","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/synthetic-quality-filter.md","filePath":"llm/synthetic-quality-filter.md","lastUpdated":1791063341000}'),d={name:"llm/synthetic-quality-filter.md"};function p(F,E,m,h,u,f){const t=C("Mermaid");return l(),o("div",null,[E[2]||(E[2]=B('<h1 id="质量过滤-打分器与一致性" tabindex="-1">质量过滤：打分器与一致性 <a class="header-anchor" href="#质量过滤-打分器与一致性" aria-label="Permalink to &quot;质量过滤：打分器与一致性&quot;">​</a></h1><div class="epigraph"><p>过滤器不是在挑「好样本」，是在把教师分布投影到你声明的目标分布上——投影错了方向，数据越多离目标越远。</p><footer>—— 据 Chen 等 AlpaGasus；Zheng 等 LLM-as-judge 整理</footer></div><p><a href="/llm/self-instruct-evol">上一课</a>把自举与演化接成了题池扩张机，但扩张进来的一切都只是候选。把候选变成训练集的关卡是过滤：启发式、判别式分类器、生成式打分器三层递进。预训练网页侧的过滤在<a href="/llm/data-quality-filter">质量过滤与分类器</a>与 <a href="/llm/dclm-filter">DCLM 数据过滤</a>已讲；本课写指令与轨迹侧的打分器：监督信号是教师的判断而非参照文档，失败模式因此不同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>合成数据的过滤难点在于「质量」没有外部定义。网页数据至少有「像高质量文档」这个参照；指令数据的「好」取决于目标能力——同一套数据做聊天助手是好，做数学推理是噪声。工程错误有两类。其一，只用一套固定打分器，把教师的风格偏好当成质量：长答案与讨好语气被系统性打高分。其二，只用一次性打分，把裁判的随机性当成样本属性：同一样本两次打分可能跨两档。两者的共同后果是过滤器在系统性地选择一种风格，训练分布被投影到「教师喜欢的样子」而不是「任务需要的样子」。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三层过滤各拦各的。启发式层拦结构与格式：长度界、语言检测、格式完整性、模板残留，便宜且近乎无偏置，但只看得见表层。判别式层用小分类器放大规模：人工分层样本作正例，扫全量候选；预训练侧 DCLM 已证明对齐良好的 fastText 能压过多数复杂启发式，指令侧同理，成本在标注集要覆盖目标能力。生成式打分器层用教师或裁判逐条打分或做成对比较，粒度最细、偏置也最大——要冻结提示、温度与解析规则，把裁判当成有版本的代码。<span class="marginnote">三层顺序可以类比机场安检：X 光机（启发式）先快速拦下明面违禁品，证件核验（分类器）统一过每个人，最后才由人工复检（裁判）处理疑难件。把最贵的人力放在队伍最前面，队伍立刻堵死——所以必须先便宜后贵。</span></p><p>一致性的三个检查。样本内自洽：同一样本多次打分的方差，方差大的送人审或丢弃。裁判间一致：两个不同模型（或教师加规则）交叉打分，分歧样本信息量最大——分歧小而系统化说明裁判同源，分歧大说明质量信号本身不稳。与人标锚定：留一小批人标注做校准集，定期算裁判与人的一致率，漂移要在污染配比前发现。<span class="marginnote">给个数字实例：同一样本让裁判打 5 次得 4、4.5、4、4.2、4.1，方差小，放行；若得 5、2、4、1.5、3.5，裁判自己都拿不准，进人审。再看裁判间：教师给 4 分、独立小模型给 1 分，这种分歧本身就是最值得人看的信号。</span></p>',8)),(l(),s(r,null,{default:e(()=>[i(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAND%5B%22%E5%80%99%E9%80%89%E6%B1%A0%22%5D%20--%3E%20HEUR%5B%22%E5%90%AF%E5%8F%91%E5%BC%8F%EF%BC%9A%E7%BB%93%E6%9E%84%E4%B8%8E%E6%A0%BC%E5%BC%8F%22%5D%0A%20%20HEUR%20--%3E%20CLF%5B%22%E5%88%A4%E5%88%AB%E5%BC%8F%E5%88%86%E7%B1%BB%E5%99%A8%EF%BC%9A%E5%85%A8%E9%87%8F%E6%89%AB%22%5D%0A%20%20CLF%20--%3E%20LLM%5B%22%E7%94%9F%E6%88%90%E5%BC%8F%E6%89%93%E5%88%86%E5%99%A8%EF%BC%9A%E6%95%99%E5%B8%88%E6%88%96%E8%A3%81%E5%88%A4%22%5D%0A%20%20LLM%20--%3E%20VAR%7B%22%E6%A0%B7%E6%9C%AC%E5%86%85%E6%96%B9%E5%B7%AE%E5%A4%A7%EF%BC%9F%22%7D%0A%20%20VAR%20--%3E%7C%E6%98%AF%7C%20HUMAN%5B%22%E9%80%81%E4%BA%BA%E5%AE%A1%E6%88%96%E4%B8%A2%E5%BC%83%22%5D%0A%20%20VAR%20--%3E%7C%E5%90%A6%7C%20CROSS%7B%22%E8%A3%81%E5%88%A4%E9%97%B4%E5%88%86%E6%AD%A7%E5%A4%A7%EF%BC%9F%22%7D%0A%20%20CROSS%20--%3E%7C%E6%98%AF%7C%20HUMAN%0A%20%20CROSS%20--%3E%7C%E5%90%A6%7C%20IN%5B%22%E5%85%A5%E5%BA%93%EF%BC%8C%E5%B8%A6%E8%BF%87%E6%BB%A4%E7%89%88%E6%9C%AC%E5%8F%B7%22%5D%0A%20%20ANCH%5B%22%E4%BA%BA%E6%A0%87%E6%A0%A1%E5%87%86%E9%9B%86%22%5D%20--%3E%20LLM%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[A("过滤的真实作用是重加权：每一道关卡都在改写样本进入训练分布的概率，阈值就是权重曲线。这意味着「过滤掉多少」不是质量指标，被保留集合的分布才是——AlpaGasus 用裁判从 5.2 万条 Alpaca 数据里筛出约 9 千条，训练更快、评测更高，说明被筛掉的部分不少是负迁移。反过来，过滤器太窄会把高难样本当低质量丢掉：长链条多步推理在打分器眼里「可读性」天然差，质量与难度在裁判那里是混着的——难度问题本课程后面用通过率单独解决，过滤器不要越权替它做决定。打分器还有实证的自我偏好（"),a("a",{href:"/llm/self-preference-bias"},"自我偏好"),A("）：裁判对出自自身风格的样本系统性偏高，所以生成与打分应尽量分离。一致性检查的机制意义在于分离两种误差：样本内方差量的是裁判的随机误差，裁判间分歧量的是系统性偏置——只查前者会漏掉最危险的后者。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"AlpaGasus 的 5.2 万到 9 千不是「删脏数据」那么简单：它同时把训练时间缩短到几分之一。过滤器太弱时，「更多数据」掩盖的常常是负迁移——数量从来不是质量的上位替代。")],-1)),(l(),s(r,null,{default:e(()=>[i(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%90%8C%E4%B8%80%E6%A0%B7%E6%9C%AC%22%5D%20--%3E%20R1%5B%22%E8%A3%81%E5%88%A4A%E7%AC%AC1%E6%AC%A1%EF%BC%9A4%E5%88%86%22%5D%0A%20%20S%20--%3E%20R2%5B%22%E8%A3%81%E5%88%A4A%E7%AC%AC2%E6%AC%A1%EF%BC%9A2%E5%88%86%22%5D%0A%20%20S%20--%3E%20R3%5B%22%E8%A3%81%E5%88%A4B%EF%BC%9A4.5%E5%88%86%22%5D%0A%20%20R1%20--%3E%20V%7B%22%E8%A3%81%E5%88%A4A%E8%87%AA%E5%B7%B1%E6%96%B9%E5%B7%AE%E5%A4%A7%EF%BC%9F%22%7D%0A%20%20R2%20--%3E%20V%0A%20%20V%20--%3E%7C%E6%98%AF%7C%20RN%5B%22%E9%9A%8F%E6%9C%BA%E8%AF%AF%E5%B7%AE%EF%BC%9A%E9%80%81%E4%BA%BA%E5%AE%A1%E6%88%96%E4%B8%A2%E5%BC%83%22%5D%0A%20%20V%20--%3E%7C%E5%90%A6%7C%20X%7B%22%E4%B8%8E%E8%A3%81%E5%88%A4B%E5%88%86%E6%AD%A7%E5%A4%A7%EF%BC%9F%22%7D%0A%20%20R3%20--%3E%20X%0A%20%20X%20--%3E%7C%E6%98%AF%7C%20BI%5B%22%E7%B3%BB%E7%BB%9F%E5%81%8F%E7%BD%AE%EF%BC%9A%E6%9F%A5%E5%90%8C%E6%BA%90%E4%B8%8E%E8%87%AA%E6%88%91%E5%81%8F%E5%A5%BD%22%5D%0A%20%20X%20--%3E%7C%E5%90%A6%7C%20OK%5B%22%E5%85%A5%E5%BA%93%EF%BC%8C%E5%B8%A6%E8%BF%87%E6%BB%A4%E7%89%88%E6%9C%AC%E5%8F%B7%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=B('<p><span class="marginnote">这张图回答的问题是：两种一致性检查各量什么。样本内方差量的是裁判的随机误差——同一把尺子量几次读数不稳；裁判间分歧量的是系统偏置——两把尺子从根上刻度就不一样。只查前者，会漏掉后者这种最危险的误差。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>打分器的上限是教师的上限，且教师不会说「我不会」：超出教师能力的样本不会被标成低质量，只会被标成「不像教师」，这类样本的缺失在池内无从察觉，只能靠 held-out 真题的增量审计兜底。三层过滤顺序有讲究：贵的放后面，先启发式压量再上裁判，反过来会把预算烧在显然的坏样本上。最后，过滤阈值的任何变动都会改变配比——过滤器与配比是同一根轴上的两个旋钮，消融时不能分开归因，这一点留给配方消融课展开。<span class="marginnote">初学者容易以为「阈值调严一点总没错」。实际上每次调阈值都在改写配比：多步推理长链因「可读性差」被滤掉，推理能力就悄悄下滑——动过滤器等于动配比，归因时两个旋钮要一起消融。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三层过滤：启发式拦格式，分类器扫全量，打分器给细粒度。</li><li>质量是相对目标能力的声明，不是样本的内禀属性。</li><li>一致性三查：样本内方差量随机误差，裁判间分歧量系统偏置，人标锚定防漂移。</li><li>过滤即重加权：看被保留集合的分布，不看过滤比例。</li><li>生成与打分分离，防自我偏好变成自选择。</li><li>出处：Chen 等 AlpaGasus 2023；Zheng 等 2023；DCLM 2024。</li></ul>',5))])}const _=n(d,[["render",p]]);export{c as __pageData,_ as default};
